jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // Audience gate REMOVED 2026-09-15 — this tool is now available to
  // everyone, so tool_configs `audience: ["all"]` is the only filter.
  // The in-tool email allowlist had to go with it: left in place it would
  // have installed for the team and then silently returned for every one
  // of them, which is worse than not shipping.

  // ─── Agent registry ───────────────────────────────────────────────
  // V1 ships with one agent (apply_instruction → "Revise Document").
  // Adding agent #2 = push another entry; the dropdown + Manage Agents
  // modal are data-driven off this list. displayName is what the user
  // sees; id is what flows through dispatch payloads + IDB keys.
  var AGENT_REGISTRY = [
    {
      id: "apply_instruction",
      displayName: "Revise Document",
      icon: "🤖",
      description: "Make multiple edits across the doc based on a free-form instruction (e.g., \"Make this Colgate-friendly\", \"Shorten by 30%\").",
      inputMode: "instruction",
      defaultSettings: {
        tone: "balanced",  // conservative | balanced | aggressive
        scope: ["payment-terms", "indemnity", "termination", "ip", "mfn", "audit", "warranty"],
      },
    },
    {
      id: "address_comments",
      displayName: "Address Comments",
      icon: "📧",
      description: "Paste or drop an email/comment thread and the agent proposes edits responding to each comment, cites the email language behind each edit, and drafts a response email at the end.",
      inputMode: "compose",
      defaultSettings: {
        tone: "balanced",
      },
    },
    {
      id: "draft_agreement",
      displayName: "Draft Agreement",
      icon: "📝",
      description: "Guided Q&A to generate a contract from scratch. Asks the right intake questions, drafts each section using your playbooks, lets you review per-section before inserting into the doc.",
      inputMode: "interview",
      defaultSettings: {
        tone: "balanced",
        insertMode: "current", // "current" = insert into open doc; "newdoc" reserved for v2
      },
    },
    {
      id: "research",
      displayName: "Research",
      icon: "🔎",
      description: "Answers a legal or drafting question from ELI's own sources — the playbook, team guidance and the clause library — and says plainly when nothing on file covers it rather than answering from general knowledge alone.",
      inputMode: "instruction",
      defaultSettings: {
        tone: "balanced",
        // Which sources may be drawn on, in precedence order. Turning one
        // off removes it from the answer AND from the citations.
        sources: ["guidance", "playbook", "clauses", "document"],
      },
    },
  ];

  // ─── Per-user agent settings (IDB) ────────────────────────────────
  // One row per agent id under config store. Settings ride on the
  // agent_settings shape: { enabled, tone, scope }. Defaults derive
  // from the registry's defaultSettings until the user overrides.
  var SETTINGS_KEY_PREFIX = "eli_agent_settings_";
  function _settingsKey(agentId) { return SETTINGS_KEY_PREFIX + agentId; }
  function _getAgentSettings(agentId) {
    var entry = _findAgent(agentId);
    if (!entry) return Promise.resolve(null);
    return eli.storage.get("config", _settingsKey(agentId)).then(function (row) {
      var saved = (row && row.settings) || {};
      return Object.assign(
        { enabled: true },
        entry.defaultSettings || {},
        saved
      );
    }).catch(function () {
      return Object.assign({ enabled: true }, entry.defaultSettings || {});
    });
  }
  function _setAgentSettings(agentId, settings) {
    if (!_findAgent(agentId)) return Promise.reject(new Error("Unknown agent id: " + agentId));
    return eli.storage.put("config", {
      key: _settingsKey(agentId),
      agentId: agentId,
      settings: settings || {},
      updatedAt: new Date().toISOString(),
    });
  }
  function _findAgent(id) {
    for (var i = 0; i < AGENT_REGISTRY.length; i++) {
      if (AGENT_REGISTRY[i].id === id) return AGENT_REGISTRY[i];
    }
    return null;
  }
  // Returns the public registry projection — what callers see via
  // list_agents dispatch. Strips internal fields, joins persisted
  // enable state per row. Async because settings live in IDB.
  function _listAgents() {
    return Promise.all(AGENT_REGISTRY.map(function (a) {
      return _getAgentSettings(a.id).then(function (s) {
        return {
          id: a.id,
          displayName: a.displayName,
          icon: a.icon,
          description: a.description,
          enabled: s.enabled !== false,
        };
      });
    }));
  }

  // ─── Active mode state ────────────────────────────────────────────
  // _currentMode: "ask_eli" (default Q&A) OR "agent:<agentId>".
  // Used by intercept_submit to decide whether to take over a Send
  // click in ask_eli, and by the dropdown UI to show the active row.
  // Resets to "ask_eli" on overlay close (per Phase 1 spec).
  var _currentMode = "ask_eli";
  function _setMode(mode) {
    _currentMode = mode;
    _onModeChange(mode);
  }
  function _onModeChange(mode) {
    // Tint the caret + ask_eli title so the user sees at a glance
    // when an agent mode is active (vs default Q&A). No label
    // changes — title stays "Ask ELI" per the user-facing design.
    document.querySelectorAll("[data-eli-agent-dropdown-trigger]").forEach(function (caret) {
      if (mode === "ask_eli") caret.classList.remove("_eg_caret_active");
      else caret.classList.add("_eg_caret_active");
      // Tooltip reflects current mode for quick verification.
      var label = _currentDropdownLabel(mode);
      caret.title = "Mode: " + label.icon + " " + label.text + " — click to switch";
    });
  }
  function _currentDropdownLabel(mode) {
    if (mode === "ask_eli") return { icon: "💬", text: "Ask Eli" };
    var agentId = mode.replace(/^agent:/, "");
    var a = _findAgent(agentId);
    return a ? { icon: a.icon, text: a.displayName } : { icon: "💬", text: "Ask Eli" };
  }

  // ─── Dropdown painter — listens for ask_eli's mount event ─────────
  // ask_eli emits 'ask_eli:input_mounted' after rendering its chat
  // input bar with { slotEl, sendBtn, inputEl, getQaContext }. We
  // paint the dropdown into slotEl, mark the send button so we can
  // flip its label on mode change, and rely on intercept_submit
  // (registered below) to take over when an agent mode is active.
  function _paintDropdown(payload) {
    var slot = payload && payload.slotEl;
    var sendBtn = payload && payload.sendBtn;
    if (!slot) return;
    if (sendBtn) sendBtn.setAttribute("data-eli-agent-send-btn", "1");
    // Kept so the chat input can be locked while the agent is waiting on
    // an answer — see _syncAskInputLock.
    _askSendBtn = sendBtn || null;
    _askInputEl = (payload && payload.inputEl) || null;

    // Just a clickable caret next to the title — NO button chrome.
    // Reads as "the title has a dropdown affordance," not "there is
    // a separate button you might mistake for an action." When an
    // agent mode is active, the caret tints amber to signal state
    // without changing the title text.
    slot.innerHTML =
      '<span class="_eg_auto_toggle" data-eli-agent-auto="1" role="switch" ' +
        'title="Auto: let ELI decide whether to answer or revise the document">' +
        '<span class="_eg_auto_track"><span class="_eg_auto_knob"></span></span>' +
        '<span class="_eg_auto_label">Auto</span>' +
      '</span>' +
      '<span class="_eg_caret_inline" data-eli-agent-dropdown-trigger="1" ' +
      'title="Switch mode (Ask Eli vs an agent)">▾</span>';

    var trigger = slot.querySelector('[data-eli-agent-dropdown-trigger="1"]');
    if (trigger) trigger.onclick = function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      _openDropdownMenu(trigger);
    };
    var auto = slot.querySelector('[data-eli-agent-auto="1"]');
    if (auto) auto.onclick = function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      _setAutoRoute(!_autoRoute);
    };
    _paintAutoToggle();

    // Sync initial state (caret color) in case mode was set before mount.
    _onModeChange(_currentMode);
  }

  // ─── Chat input lock ──────────────────────────────────────────────
  // While the agent is waiting on an answer, Ask ELI's own send arrow sits
  // right there — and pressing it sends the answer into the chat as a new
  // question instead of into the agent. So the input is greyed out and the
  // agent's own buttons are scrolled into view.
  //
  // Recomputed on EVERY render and on close, never toggled one-way: a run
  // that errors, is cancelled, or is closed mid-question must not be able
  // to leave the user's chat box disabled. The only state that locks it is
  // "clarify", and anything else unlocks.
  var _askSendBtn = null;
  var _askInputEl = null;
  // `force` of false unlocks unconditionally — used on close, where there
  // may be no status left to read.
  function _syncAskInputLock(force) {
    var lock = force === false
      ? false
      : !!(_egActive && _egActive.status === "clarify");
    [_askInputEl, _askSendBtn].forEach(function (el) {
      if (!el) return;
      try {
        if (lock) {
          el.setAttribute("disabled", "disabled");
          el.classList.add("_eg_ask_locked");
          if (el === _askInputEl) {
            el.setAttribute("data-eg-ph", el.getAttribute("placeholder") || "");
            el.setAttribute("placeholder", "Answer the question above to continue…");
          }
        } else {
          el.removeAttribute("disabled");
          el.classList.remove("_eg_ask_locked");
          if (el === _askInputEl && el.hasAttribute("data-eg-ph")) {
            el.setAttribute("placeholder", el.getAttribute("data-eg-ph"));
            el.removeAttribute("data-eg-ph");
          }
        }
      } catch (_) { /* the chat may have re-rendered underneath us */ }
    });
  }

  // ─── [AUTO-ROUTE] ─────────────────────────────────────────────────
  // Step 0. With the toggle ON, what you type is read first and sent
  // either to Ask ELI's normal Q&A or to Revise Document. With it OFF —
  // the default — Ask ELI behaves exactly as it always has, and this
  // block does nothing at all.
  //
  // Three rules make it safe to leave on:
  //   1. It only ever chooses between ANSWER and Revise Document. No
  //      other agent, no other action.
  //   2. It fails to ANSWER. A classifier that errors, times out, or
  //      returns anything unexpected means a normal answer — being
  //      wrongly answered costs a re-send, being wrongly routed starts
  //      a multi-pass run over the document.
  //   3. Routing is never silent: the chat says what it decided and
  //      offers the other path in one click.
  // TO REMOVE: delete to [/AUTO-ROUTE] + the toggle in _paintDropdown +
  // the auto branch in intercept_submit.
  var AUTO_KEY = "eli_agent_auto_route";
  // ON by default, for everyone. Turning it off is a choice that sticks.
  //
  // Only an explicit "0" turns it off, so someone who has never touched the
  // toggle gets it on and someone who turned it off keeps it off. Off used
  // to REMOVE the key, which made "off" and "never set" the same state —
  // the default could not have been flipped without silently overriding
  // everyone who had already said no.
  var _autoRoute = true;

  function _loadAutoRoute() {
    try {
      var v = eli.compat && typeof eli.compat.lsGet === "function"
        ? eli.compat.lsGet(AUTO_KEY) : null;
      _autoRoute = v !== "0";
    } catch (_) { _autoRoute = true; }
  }
  function _setAutoRoute(on) {
    _autoRoute = !!on;
    try {
      if (eli.compat && typeof eli.compat.lsSet === "function") {
        eli.compat.lsSet(AUTO_KEY, _autoRoute ? "1" : "0");
      }
    } catch (_) {}
    _paintAutoToggle();
    eli.log.event("tool", "eli_agent_auto_route", { on: _autoRoute });
  }
  function _paintAutoToggle() {
    var el = document.querySelector('[data-eli-agent-auto="1"]');
    if (!el) return;
    el.className = "_eg_auto_toggle" + (_autoRoute ? " _eg_auto_on" : "");
    el.setAttribute("aria-checked", _autoRoute ? "true" : "false");
    el.setAttribute("title", _autoRoute
      ? "Auto is ON — ELI decides whether to answer or revise the document"
      : "Auto: let ELI decide whether to answer or revise the document");
  }

  function _buildRouterPrompt(text) {
    return [
      "Decide what the user wants done with the contract open in front of them.",
      "",
      "ANSWER  — they want to know something. A question, a request to explain,",
      "          summarise, compare, find, or check. Nothing in the document changes.",
      "REVISE  — they want the document CHANGED. An instruction to add, remove,",
      "          rewrite, tighten, cap, extend, convert, or make it favour someone.",
      "",
      "Return JSON only: { \"route\": \"ANSWER\" | \"REVISE\", \"confidence\": 1-5, \"why\": \"a few words\" }",
      "",
      "RULES:",
      "1. If it is phrased as a question, it is ANSWER — even a question about",
      "   something that could be changed. \"Can we cap liability?\" is ANSWER.",
      "   \"Cap liability at 12 months\" is REVISE.",
      "2. Asking what SHOULD change is ANSWER. Telling it to change is REVISE.",
      "   \"What would you change here?\" is ANSWER.",
      "3. When it could be either, choose ANSWER. Answering something they wanted",
      "   revised costs one more message; revising something they only asked about",
      "   rewrites their contract.",
      "4. confidence 1-2 means you are unsure — the caller treats that as ANSWER.",
      "",
      "═══ WHAT THEY TYPED ═══",
      String(text || "").slice(0, 1200),
    ].join("\n");
  }

  // Most messages are not ambiguous, and a model round-trip to decide that
  // "make this a three-way NDA" is an instruction is latency spent on a
  // foregone conclusion. These two tests settle the common cases in
  // microseconds and only what survives them costs a call.
  //
  // The two lists are deliberately lopsided. ANSWER is the safe direction,
  // so its list is generous. REVISE starts a rewrite of the document, so
  // its list is short, sentence-initial only, and gives way to anything
  // that looks like a question.
  var RE_ASKS = new RegExp("^(?:what|why|how|when|where|who|which|whose|is|are|was|were|do|does|did|can|could|should|would|will|may|might|explain|summari[sz]e|summary|describe|tell me|show me|find|list|compare|check|review|look|are there|is there|any )\\b", "i");
  var RE_EDITS = new RegExp("^(?:make|change|add|remove|delete|drop|strike|replace|rewrite|revise|redline|amend|update|revert|cap|extend|shorten|tighten|loosen|broaden|narrow|convert|turn|insert|append|swap|switch|reword|renumber|fix|set)\\b", "i");
  // "make sure the cap is 12 months" is a check, not an instruction to edit.
  var RE_EDIT_NOT = new RegExp("^(?:make|check|see)\\s+(?:sure|certain|whether|if)\\b", "i");

  function _fastRoute(t) {
    if (/\?/.test(t)) return "ANSWER";            // a question mark anywhere
    if (RE_ASKS.test(t)) return "ANSWER";
    if (RE_EDIT_NOT.test(t)) return "ANSWER";
    if (RE_EDITS.test(t)) return "REVISE";
    return null;                                   // ambiguous — ask the model
  }

  // Resolves "ANSWER" or "REVISE". Never rejects.
  function _routeInstruction(text) {
    var t = String(text || "").trim();
    if (!t) return Promise.resolve("ANSWER");
    var fast = _fastRoute(t);
    if (fast) {
      if (fast === "REVISE") _lastRouteWhy = "reads as an instruction";
      return Promise.resolve(fast);
    }
    // Wrapped: a SYNCHRONOUS throw here escapes the .catch below entirely
    // and reaches ask_eli's try/catch, which swallows it — the message then
    // silently falls through to Q&A with nothing to show for it. That is
    // exactly how this shipped broken.
    var call;
    try {
      // Same model as everything else — only the OUTPUT is capped. The
      // answer is two words and a number, so there is no reason to let it
      // generate more, and generation length is what the wait is made of.
      call = _aiJsonCall(_buildRouterPrompt(t),
        { route: "string", confidence: "number", why: "string" },
        { maxTokens: 64, temperature: 0 });
    } catch (e) {
      eli.log.event("tool", "eli_agent_route_threw", { msg: (e && e.message) || "?" });
      return Promise.resolve("ANSWER");
    }
    if (!call || typeof call.then !== "function") return Promise.resolve("ANSWER");
    return call
      .then(function (r) {
        if (!r) return "ANSWER";
        var route = String(r.route || "").toUpperCase();
        var conf = Number(r.confidence) || 0;
        if (route !== "REVISE" || conf < 3) return "ANSWER";
        _lastRouteWhy = String(r.why || "").slice(0, 80);
        return "REVISE";
      })
      .catch(function () { return "ANSWER"; });   // fail to ANSWER, always
  }
  var _lastRouteWhy = "";
  // ─── [/AUTO-ROUTE] ────────────────────────────────────────────────

  // Opens the floating menu anchored to the trigger button. List is
  // built fresh each open (so a Manage-Agents enable/disable change
  // takes effect without a full re-paint).
  function _openDropdownMenu(triggerEl) {
    _closeDropdownMenu();
    _listAgents().then(function (agents) {
      var rect = triggerEl.getBoundingClientRect();
      var menu = document.createElement("div");
      menu.id = "_eg_dropdown_menu";
      menu.style.cssText =
        "position:fixed;top:" + (rect.bottom + 4) + "px;left:" + rect.left + "px;" +
        "z-index:99999;background:#fff;border:1px solid #cbd5e1;" +
        "box-shadow:0 8px 24px rgba(15,23,42,0.18);min-width:240px;" +
        "font-family:Inter,'Segoe UI',system-ui,sans-serif;font-size:12px;";
      var rows = '';
      // Always-present Ask Eli row.
      rows += _menuRowHtml({ value: "ask_eli", icon: "💬", label: "Ask Eli", isActive: _currentMode === "ask_eli" });
      // Divider then enabled agents.
      var enabled = agents.filter(function (a) { return a.enabled; });
      if (enabled.length) rows += '<div class="_eg_menu_divider"></div>';
      enabled.forEach(function (a) {
        rows += _menuRowHtml({
          value: "agent:" + a.id, icon: a.icon, label: a.displayName,
          isActive: _currentMode === ("agent:" + a.id),
        });
      });
      // Footer — always-present Manage Agents action.
      rows += '<div class="_eg_menu_divider"></div>';
      rows += _menuRowHtml({ value: "__manage", icon: "⚙", label: "Manage Agents…", isActive: false, isAction: true });
      menu.innerHTML = rows;
      document.body.appendChild(menu);

      menu.querySelectorAll("[data-eg-menu-row]").forEach(function (row) {
        row.onclick = function () {
          var value = row.getAttribute("data-eg-menu-row");
          _closeDropdownMenu();
          if (value === "__manage") { _openManageAgentsModal(); return; }
          _setMode(value);
        };
      });
      // Outside-click closes menu.
      setTimeout(function () {
        document.addEventListener("mousedown", _outsideMenuClick, true);
      }, 0);
    });
  }
  function _menuRowHtml(opts) {
    var bg = opts.isActive ? "background:#dbeafe;color:#1e3a8a;" : "background:#fff;color:#0f172a;";
    return '<div data-eg-menu-row="' + _esc(opts.value) + '" class="_eg_menu_row' + (opts.isAction ? ' _eg_menu_row_action' : '') + '" ' +
      'style="display:flex;align-items:center;gap:8px;padding:8px 12px;cursor:pointer;' + bg + '">' +
        '<span style="font-size:13px;width:18px;text-align:center;">' + _esc(opts.icon) + '</span>' +
        '<span style="font-weight:' + (opts.isActive ? '700' : '500') + ';">' + _esc(opts.label) + '</span>' +
      '</div>';
  }
  function _closeDropdownMenu() {
    var existing = document.getElementById("_eg_dropdown_menu");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    document.removeEventListener("mousedown", _outsideMenuClick, true);
  }
  function _outsideMenuClick(ev) {
    var menu = document.getElementById("_eg_dropdown_menu");
    if (!menu) return;
    if (menu.contains(ev.target)) return;
    // Don't close if the user clicked the trigger again — that's a
    // toggle which the trigger's own handler will manage.
    var trig = ev.target.closest && ev.target.closest("[data-eli-agent-dropdown-trigger]");
    if (trig) return;
    _closeDropdownMenu();
  }

  // ─── Agent overlay — status-driven body, auto-kicks plan ─────────
  // States: capturing | planning | review | applying | applied | error
  // Header stays constant; body re-renders per status. Plan kicks
  // off automatically on overlay open (user already typed +
  // submitted in ask_eli, no need to ask twice). Cancel during
  // planning aborts the in-flight AI call.
  function _openAgentOverlay(payload) {
    _closeAgentOverlay();
    var agentId = payload && payload.agent;
    var instruction = (payload && payload.instruction) || "";
    var agent = _findAgent(agentId);
    if (!agent) {
      eli.log.event("tool", "eli_agent_open_unknown", { agent: agentId });
      return;
    }
    // 2026-05-17 v22: telemetry recording per-agent launch. Stat name
    // is per-agent (e.g. "appOpenedAgentReviseDocument") so usage_viewer
    // can break out which agent the user is actually running.
    try {
      if (eli.stats && eli.stats.record) {
        var _agStat = "appOpenedAgent" + String(agentId || "Unknown")
          .replace(/(?:^|[_\-\s])([a-z])/g, function (_m, ch) { return ch.toUpperCase(); })
          .replace(/[^A-Za-z0-9]/g, "");
        eli.stats.record(_agStat);
      }
    } catch (_) {}

    _egActive = {
      agent: agentId,
      agentDef: agent,       // full registry entry (for inputMode + display)
      instruction: instruction,
      qaIndex: (payload && payload.qaIndex) || null,
      docHash: (payload && payload.docHash) || null,
      // Auto sent this here rather than answering it — the review says so.
      routedAuto: !!(payload && payload.routedAuto),
      plan: null,
      acceptance: {},        // editId → "accepted"|"rejected"|"pending"
      editOverrides: {},     // editId → {replacementText: "user-edit"}
      // Email-to-Redline mode-specific state.
      commentSource: "",     // raw email/comments blob from the compose pane
      parsedComments: null,  // [{id, author, scope, ask, severity, originalText, skipped?}]
      responseEmail: null,   // generated response text after apply
      // Draft Agreement mode-specific state.
      interview: {
        seed: instruction || "",                    // user's initial prompt becomes Q0
        turns: [],                                  // [{question, answers, type:"choice|text|form"}]
        nextQuestions: null,                        // pending agent questions after a turn
        agreementType: null,                        // detected/picked
        intakeComplete: false,                      // user clicked "Generate draft"
      },
      outline: null,                                // [{id, name, focus, status, content?}]
      draftAcceptance: {},                          // sectionId → "accept|skip"
      draftInsertResult: null,                      // {inserted: N, failures: []}
      status: agent.inputMode === "compose" ? "compose" :
              agent.inputMode === "interview" ? "interview" : "capturing",
      error: null,
      applyResult: null,     // {applied, failures} after apply
      cancelToken: null,     // eli.cancel.token() during planning
      openedAt: new Date().toISOString(),
    };

    // Home is Ask ELI's chat. The whole flow — progress, questions,
    // review, apply — renders into a panel in the transcript, because a
    // floating window is a second place to look at work that belongs
    // beside the conversation that started it.
    //
    // The body element carries the SAME id either way, so every screen
    // and every wire-up below is unchanged by where it lives.
    _egActive.inChat = _mountInChat(agent);
    if (!_egActive.inChat) {
      var ov = document.createElement("div");
      ov.id = "_eli_agent_overlay";
      ov.className = "_eg_overlay";
      ov.innerHTML =
        '<div id="_eg_header" class="_eg_header">' +
          '<div class="_eg_header_title">' +
            '<span class="_eg_header_icon">' + _esc(agent.icon) + '</span>' +
            '<span class="_eg_header_label">' + _esc(agent.displayName) + '</span>' +
          '</div>' +
          '<div class="_eg_header_actions">' +
            '<button id="_eg_close" type="button" class="_eg_btn_ghost" title="Close">✕</button>' +
          '</div>' +
        '</div>' +
        '<div id="_eg_body" class="_eg_body"></div>';
      document.body.appendChild(ov);

      var headerEl = document.getElementById("_eg_header");
      if (typeof window._eliMakeDraggable === "function" && headerEl) {
        try { window._eliMakeDraggable(ov, headerEl); } catch (_) {}
      }
      if (typeof window._eliMakeResizable === "function") {
        try { window._eliMakeResizable(ov); } catch (_) {}
      }
      document.getElementById("_eg_close").onclick = _closeAgentOverlay;
    }

    eli.log.event("tool", "eli_agent_overlay_opened", {
      agent: agentId,
      instructionLen: (instruction || "").length,
    });

    // Render initial body. Plan only auto-kicks when this agent
    // takes its input directly from the chat box (instruction mode).
    // Compose/interview modes wait for the user to finish the
