    return _bodyHeader() +
      '<div class="_eg_applied_box">' +
        '<div class="_eg_applied_title">✓ Inserted ' + r.inserted + ' section' + (r.inserted === 1 ? "" : "s") + ' into the document.</div>' +
        '<div class="_eg_applied_sub">Review the inserted text in Word. Use Word\'s normal edit/format tools to tune typography.</div>' +
      '</div>' +
