  // ─── Review body — strategy + unrequested + cards + mini-map ──────
  // The coverage verdict. Shown whether it passed or failed — "I read the
  // result and it does what you asked" is information, and its absence
  // after a failure would be indistinguishable from silence.
  function _renderCoverageSection(c) {
    if (!c) return "";
    if (c.error) {
      return '<div class="_eg_verify_box">' +
        '<div class="_eg_verify_title">⚠ Coverage check did not run</div>' +
        '<div class="_eg_verify_row">' + _esc(c.error) +
        ' — these edits have NOT been checked against your request as a whole.</div>' +
      '</div>';
    }
    var ok = c.achieved !== false;
    var list = c.checklist || [];
    var met = list.filter(function (x) { return x.satisfied; }).length;
    // A requirement about a notice or signature block is not a gap in the
    // agent's work — it is yours, because ELI does not edit those. Shown as
    // such rather than as a failure it could never clear.
    var byHand = list.filter(function (x) { return !x.satisfied && x.handover; }).length;
    // The checklist IS the output. Showing only a verdict would hide which
    // requirement failed, which is the part worth reading.
    var rows = list.map(function (x) {
      var hand = !x.satisfied && x.handover;
      var mark = x.satisfied ? "✓" : (hand ? "✎" : "✗");
      var cls = x.satisfied ? "_eg_audit_ok" : (hand ? "_eg_audit_hand" : "_eg_audit_gap");
      return '<div class="_eg_audit_row ' + cls + '">' +
        '<span class="_eg_audit_mark">' + mark + '</span>' +
        '<span class="_eg_audit_text">' + _esc(x.text) +
          (x.where ? ' <em>' + _esc(x.where) + '</em>' : '') +
          (hand ? ' <b>(yours — ELI does not edit ' + _esc(x.handover) +
            ' blocks; see the follow-up)</b>' : '') +
          (!hand && !x.reported ? ' <b>(not reported by the audit — treated as unmet)</b>' : '') +
          (x.note ? '<div class="_eg_audit_note">' + _esc(x.note) + '</div>' : '') +
          (x.evidence ? '<div class="_eg_audit_ev">“' + _esc(x.evidence) + '”</div>' : '') +
        '</span>' +
      '</div>';
    }).join("");
    return '<div class="' + (ok ? "_eg_audit_box_ok" : "_eg_audit_box") + '">' +
      '<div class="_eg_audit_head">' + (ok ? "✓ " : "⚠ ") +
        _esc(c.assessment || (ok ? "Does what you asked." : "Does not yet do what you asked.")) +
        (list.length ? ' <span class="_eg_audit_count">' + met + " of " + list.length +
          ' requirements met' + (byHand ? ", " + byHand + " for you" : "") +
          '</span>' : '') +
      '</div>' + rows +
      (c.noChecklist
        ? '<div class="_eg_audit_row _eg_audit_gap"><span class="_eg_audit_mark">!</span>' +
          '<span class="_eg_audit_text">No requirements checklist could be derived, so this ' +
          'is an unscored reading of the result rather than an audit.</span></div>'
        : '') +
    '</div>';
  }

  // ─── [VERIFY-UI] ──────────────────────────────────────────────────
  // What the deterministic pass found on the SIMULATED result. These are
  // consequences of the edit set as a whole, not defects in any one edit,
  // so they sit above the cards rather than on them. Silence here is
  // meaningful — it means the analyzers found no regression.
  // TO REMOVE: delete to [/VERIFY-UI] + its call in _bodyReview.
  function _renderVerificationSection(v) {
    if (!v || !v.ran) return "";
    var rows = [];
    if (v.nowUnused && v.nowUnused.length) {
      rows.push(["Definition left with no uses",
        v.nowUnused.join(", ") + " — the glossary entry becomes dead. Delete it too, or keep the term."]);
    }
    if (v.danglingRefs && v.danglingRefs.length) {
      rows.push(["Cross-reference now dangles",
        v.danglingRefs.join(", ") + " — the definitions section still points at a definition these edits remove."]);
    }
    if (v.termsInvented && v.termsInvented.length) {
      rows.push(["New terms introduced",
        v.termsInvented.join(", ") + " — the drafted text defines vocabulary this agreement did not use."]);
    }
    if (v.termsLost && v.termsLost.length) {
      rows.push(["Definition removed", v.termsLost.join(", ")]);
    }
    if (v.nowUndefined && v.nowUndefined.length) {
      rows.push(["Now used but never defined", v.nowUndefined.join(", ")]);
    }
    if (v.notInParagraph && v.notInParagraph.length) {
      rows.push(["Anchor text not found in its paragraph",
        v.notInParagraph.join(", ") + " — the quoted text does not appear where the plan " +
        "said it does, so these were not applied. Usually means the model paraphrased instead " +
        "of quoting."]);
    }
    if (v.multiLineWrites && v.multiLineWrites.length) {
      rows.push(["Written as multiple lines",
        v.multiLineWrites.join(", ") + " — the replacement was inserted with real line " +
        "breaks. Check the block reads correctly."]);
    }
    if (v.breaksLost && v.breaksLost.length) {
      rows.push(["Line breaks could not be inserted",
        v.breaksLost.join(", ") + " — this Word build rejected a line break, so the " +
        "replacement went in as a single line. Check the formatting."]);
    }
    if (v.anchorTooLong && v.anchorTooLong.length) {
      rows.push(["Anchor too long to pin precisely",
        v.anchorTooLong.join(", ") + " — over " + SEARCH_MAX + " characters and not a whole " +
        "paragraph, so the exact span cannot be located. These are NOT applied; re-run to " +
        "re-plan them with shorter anchors."]);
    }
    if (v.paragraphRebuilt && v.paragraphRebuilt.length) {
      rows.push(["Applied by rebuilding the paragraph",
        v.paragraphRebuilt.join(", ") + " — the anchor was too long for Word to span, so the " +
        "paragraph is rewritten around it. The wording outside the edit is preserved; " +
        "bold/italic runs inside that paragraph are not."]);
    }
    if (v.listLabels && v.listLabels.length) {
      rows.push(["List numbering removed from the text",
        v.listLabels.join(", ") + " — the model wrote the list number into the edit. Word " +
        "generates it, so the literal one was stripped; the item keeps its own numbering."]);
    }
    if (v.retargeted && v.retargeted.length) {
      rows.push(["Moved to the right paragraph",
        v.retargeted.join(", ") + " — the plan named a paragraph that does not contain the " +
        "quoted text. Retargeted to the one that does; check it landed in the right clause."]);
    }
    if (v.multiParagraph && v.multiParagraph.length) {
      rows.push(["Spans several paragraphs",
        v.multiParagraph.join(", ") + " — one edit written across consecutive items. The " +
        "whole span is replaced and Word renumbers the list. Check the item breaks."]);
    }
    if (v.rebuiltFromClean && v.rebuiltFromClean.length) {
      rows.push(["Accepts tracked changes to apply",
        v.rebuiltFromClean.join(", ") + " \u2014 these paragraphs already carry " +
        "tracked changes. Word searches the markup and the edit quotes the " +
        "clean text, so the paragraph is rebuilt from the accepted version " +
        "and your change layered on. Each is marked for your decision."]);
    }
    if (v.paragraphsMerged && v.paragraphsMerged.length) {
      rows.push(["Would merge paragraphs into one",
        v.paragraphsMerged.join(", ") + " — the quoted text runs across a paragraph break but " +
        "the replacement carries none, so those clauses become a single paragraph and Word " +
        "renumbers what follows. Marked for your decision; “Apply all” skips them."]);
    }
    if (v.multiLine && v.multiLine.length) {
      rows.push(["Spans line breaks",
        v.multiLine.join(", ") + " — a block with soft line breaks (a notices " +
        "address block, for example). The whole paragraph is replaced, so the " +
        "replacement must contain every line you want to keep."]);
    }
    if (v.wholeParagraph && v.wholeParagraph.length) {
      rows.push(["Replaces a whole paragraph",
        v.wholeParagraph.join(", ") + " — the anchor covered the entire paragraph, so the " +
        "paragraph is the target. Check the replacement keeps anything you wanted to keep."]);
    }
    if (v.unanchored && v.unanchored.length) {
      rows.push(["Could not be pinned to exact text",
        v.unanchored.length + " edit(s) — these apply to the whole paragraph, or not at all. " +
        "No document-wide search is attempted."]);
    }
    if (!rows.length) {
      return '<div class="_eg_verify_ok">✓ Checked: no definitions broken, no cross-references dangling.</div>';
    }
    return '<div class="_eg_verify_box">' +
      '<div class="_eg_verify_title">⚠ Consequences of this edit set</div>' +
      rows.map(function (r) {
        return '<div class="_eg_verify_row"><b>' + _esc(r[0]) + ':</b> ' + _esc(r[1]) + '</div>';
      }).join("") +
    '</div>';
  }
  // ─── [/VERIFY-UI] ─────────────────────────────────────────────────

  function _bodyReview() {
    var plan = _egActive.plan || { summary: "", edits: [], unrequested: [] };
    var edits = plan.edits || [];
    if (!edits.length) {
      return _bodyHeader() +
        '<div class="_eg_empty_box">' +
          '<div class="_eg_empty_title">No edits proposed</div>' +
          '<div class="_eg_empty_msg">' + _esc(plan.summary || "I read the doc but didn't find anything to change for this brief. Try rephrasing or being more specific.") + '</div>' +
        '</div>' +
        _renderUnrequestedSection(plan.unrequested) +
        '<div class="_eg_actions_row">' +
          '<button id="_eg_replan" type="button" class="_eg_btn_secondary">Try again</button>' +
        '</div>';
    }
    // Group edits by section (or category if no section).
    var groups = {};
    var groupOrder = [];
    edits.forEach(function (e) {
      var key = e.section || e.category || "Other";
      if (!groups[key]) { groups[key] = []; groupOrder.push(key); }
      groups[key].push(e);
    });
    var counts = _editCounts();
    // Edits the bulk-accept button will pass over. Counted here so both the
    // button and the stats row can say so.
    var needReview = edits.filter(function (e) {
      return e.requiresHumanReview && _egActive.acceptance[e.id] === "pending";
    }).length;
    // Everything not already written to the document and not rejected.
    // What "Apply all" will actually write: not applied, not rejected, and
    // not flagged for review. The count has to be the truth, or the button
    // promises work it then declines to do.
    var unapplied = edits.filter(function (e) {
      var st = _egActive.acceptance[e.id];
      return st !== "applied" && st !== "rejected" && !e.requiresHumanReview;
    }).length;
