  // Per-stage AI call helper — wraps eli.ai.completeJSON with a
  // fresh cancel token that the Cancel button can abort.
  // Callable OUTSIDE a run. The auto-router asks a question before any run
  // exists — deciding whether to start one is its whole job — and this used
  // to assign straight into a null _egActive, throwing synchronously before
  // any .catch() could see it. ask_eli's try/catch then swallowed it and
  // every routed instruction fell through to Q&A.
  // `extra` caps the generation for callers that need a short answer. It
  // deliberately does NOT carry `model` — every call uses the configured
  // model, and nothing here may quietly pick a different one.
  function _aiJsonCall(prompt, schema, extra) {
    var token = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token() : null;
    // Only a live run has something to cancel.
    if (_egActive) _egActive.cancelToken = token;
    var opts = { sanitize: false };
    if (extra) {
      if (extra.maxTokens) opts.maxTokens = extra.maxTokens;
      if (typeof extra.temperature === "number") opts.temperature = extra.temperature;
    }
    if (token && token.signal) opts.signal = token.signal;
    return eli.ai.completeJSON(prompt, schema, opts);
  }
  function _runStrategyPass() {
