  }
  // Critique is told to "drop edits that are pure stylistic preference,
  // duplicates, or contradict another edit" — so it deletes, and until
  // 2026-09-15 it deleted invisibly: an edit that went in here and did not
  // come out was gone with nothing on screen to say so. Record what it took,
  // by what it took it from, so a good edit removed by a bad judgement is
  // visible rather than merely absent.
  function _runCritiquePass(edits) {
    if (!edits || !edits.length) return Promise.resolve([]);
    var prompt = _buildCritiquePrompt(_egActive, edits);
    return _aiJsonCall(prompt, { edits: "object" })
      .then(function (result) {
        var refined = (result && Array.isArray(result.edits)) ? result.edits : edits;
        // Defense: if critique returned nothing, keep the originals.
        if (!refined.length) return edits;
        var kept = {};
        refined.forEach(function (e) { if (e && e.id) kept[e.id] = true; });
        var gone = edits.filter(function (e) { return !kept[e.id]; });
        if (gone.length && _egActive) {
          _egActive.critiqueDropped = gone.map(function (e) {
            return (e.section || e.id) + ": " +
              _truncate(String(e.anchorText || ""), 70);
          });
