  // ─── [RESEARCH] ───────────────────────────────────────────────────
  // Answers a question from ELI's OWN sources — team guidance, the playbook,
  // the mined clause library, and the open document — and is explicit about
  // which of those carried the answer.
  //
  // The point is not a better search box. It is that a general model will
  // always produce a confident, plausible answer about what "our position"
  // is; this one has to name the rule it read, or say nothing on file covers
  // the question. An uncited answer is downgraded to "general drafting
  // knowledge" in the UI so it can never be mistaken for house policy.
  // TO REMOVE: delete to [/RESEARCH] + the "research" registry entry, the
  // _runResearch branch in _openAgent, and the two body cases.
  var RESEARCH_MAX_CLAUSES = 14;
  var RESEARCH_SNIPPET = 700;

  // Just enough markdown for an answer: paragraphs, bullets, bold, code.
  // ESCAPES FIRST and then adds markup — the input is model output, so the
  // order is what keeps a stray "<" in a quoted clause from becoming a tag.
  function _mdBlock(text) {
    var t = String(text == null ? "" : text).replace(/\r\n/g, "\n").trim();
    if (!t) return "";
    return t.split(/\n{2,}/).map(function (para) {
      var lines = para.split("\n");
      var bullets = lines.every(function (l) { return /^\s*[-*•]\s+/.test(l); });
      if (bullets) {
        return "<ul>" + lines.map(function (l) {
          return "<li>" + _mdInline(l.replace(/^\s*[-*•]\s+/, "")) + "</li>";
        }).join("") + "</ul>";
      }
      return "<p>" + lines.map(_mdInline).join("<br>") + "</p>";
    }).join("");
  }
  function _mdInline(s) {
    return _esc(String(s || ""))
      .replace(/`([^`]{1,200})`/g, "<code>$1</code>")
      .replace(/\*\*([^*]{1,200})\*\*/g, "<b>$1</b>");
  }

  function _researchSourcesEnabled(settings) {
    var s = (settings && settings.sources) || ["guidance", "playbook", "clauses", "document"];
    var on = {};
    s.forEach(function (k) { on[k] = true; });
    return on;
  }

  // Clause cards ranked against the question. Deterministic — the library is
  // small enough that lexical scoring beats the cost and opacity of anything
  // cleverer, and a wrong retrieval here is a wrong citation.
  function _researchRankClauses(cards, question, max) {
    var q = String(question || "").toLowerCase();
    var terms = (q.match(/[a-z][a-z-]{2,}/g) || []).filter(function (w) {
      return CI_STOP.indexOf(w) === -1;
    });
    if (!terms.length) return [];
    var seen = {};
    var uniq = terms.filter(function (w) { return seen[w] ? false : (seen[w] = true); });
    return (cards || []).map(function (c) {
      var hay = (String(c.heading || "") + " " + String(c.name || "") + " " +
        (c.keyTerms || []).join(" ") + " " + String(c.head || "")).toLowerCase();
      var score = 0;
      uniq.forEach(function (w) {
        if (String(c.heading || "").toLowerCase().indexOf(w) !== -1) score += 4;  // name match is strongest
        else if (hay.indexOf(w) !== -1) score += 1;
      });
      return { card: c, score: score };
