      "{",
      '  "achieved": true|false,',
      '  "assessment": "1-2 sentences: does this document now do what was asked?",',
      '  "checklist": [',
      '    { "id": "r1", "satisfied": false,',
      '      "evidence": "by and between Colgate and Lipotype",',
      '      "note": "the preamble still names two parties" }',
      "  ],",
      '  "edits": [',
      '    { "id": "c1", "type": "replace", "paragraphId": "ELI_IDX_1",',
      '      "section": "Preamble", "anchorText": "<verbatim text from the document below>",',
      '      "replacementText": "<the corrected text>",',
      '      "rationale": "why this is still wrong", "category": "coverage",',
      '      "confidence": 4, "requiresHumanReview": false }',
      "  ]",
      "}",
      "",
      "RULES:",
      "1. `anchorText` MUST be copied verbatim from the document below, and MUST appear in the",
      "   paragraph named by `paragraphId`. If you cannot quote it exactly, omit the edit.",
      "2. Propose ONLY what is needed to satisfy the instruction. Do not improve the contract",
      "   generally — that is a different task and it is not what was asked.",
      "3. Report EVERY checklist item, satisfied or not. A checklist entry with no",
      "   verdict is worse than a failed one.",
      "4. If every requirement is satisfied, return achieved:true and an EMPTY edits",
      "   array. An empty list is a valid and useful answer — do not invent work.",
      "5. Keep anchorText under 200 characters and inside a single line.",
      "",
