    if (!payload.length) return Promise.resolve([]);
    var prompt = _buildCoveragePrompt(_egActive, payload, _egActive.verification,
      round, null, stalled);
    return _aiJsonCall(prompt,
      { achieved: "boolean", assessment: "string", checklist: "object", edits: "object" })
      .then(function (r) {
