    // Derive the checklist ONCE, from the request. Every round scores the
    // same list, so an item can be watched flipping from unmet to met.
    function _deriveRequirements() {
      if (!_egActive) return Promise.resolve();
      if (_egActive.requirements && _egActive.requirements.length) return Promise.resolve();
      return _aiJsonCall(_buildRequirementsPrompt(_egActive), { requirements: "object" })
        .then(function (r) {
          if (!_egActive) return;
          var list = (r && Array.isArray(r.requirements)) ? r.requirements : [];
          _egActive.requirements = list.map(function (x, i) {
            return {
              id: String((x && x.id) || ("r" + (i + 1))),
              text: String((x && x.text) || "").trim(),
              where: String((x && x.where) || "").trim(),
              why: String((x && x.why) || "").trim(),
            };
