  // ─── [/COVERAGE] ──────────────────────────────────────────────────

  // Edits added by a LATER round — coverage, or the post-apply re-check.
  //
  // Those rounds read a SIMULATION: the document as it would be once every
  // edit applied. So an edit they add routinely quotes text that another
  // edit creates and that the document does not contain yet. That is not a
  // mistake by the round — it is reading the right document — but it means
  // the edit cannot anchor on its own, and it has to be folded into the
  // edit that creates its text.
  //
  // They went straight to _anchorEdits with none of that. A preamble gap
  // fix reading "Resolves undefined placeholder '[[Third Party 2 Defined
  // Name]]' introduced in the preamble" quoted the preamble as the FIRST
  // round would leave it, and was refused as not in the document.
  // Returns the corrected full set and which of `added` survived.
  function _correctAddedEdits(existing, added) {
    var out = (_egActive && _egActive.conflicts) || {};
    if (_egActive) _egActive.conflicts = out;
