        if (w && typeof w.then === "function") w.catch(function () {});
      } catch (_) {}
      return true;
    }).catch(function (err) {
      if (_egActive) {
        _egActive.reindexFailed = (err && err.message) || "re-index failed";
        _stream("warn", "Could not re-index", _egActive.reindexFailed);
      }
      return false;
    });
  }

  function _runPostApplyAudit() {
    if (!_egActive) return Promise.resolve(null);
    _egActive.postAudit = { running: true };
    _renderOverlayBody();
