    var structure = (helpers && typeof eli.host.readStructuralMap === "function")
      ? eli.host.readStructuralMap().catch(function (e) {
        packet.degraded.push("structure: " + ((e && e.message) || "unavailable"));
        return null;
      })
      : Promise.resolve(null);

    // defined_terms is demand-tier; warm it before dispatching or the
    // channel isn't registered yet.
    var terms = (eli.tools && typeof eli.tools.ensureLoaded === "function")
      ? eli.tools.ensureLoaded("defined_terms").then(function () {
        var p = eli.dispatch("defined_terms", "extract", { formatting: false });
        return (p && typeof p.then === "function") ? p : null;
      }).catch(function (e) {
        packet.degraded.push("defined terms: " + ((e && e.message) || "unavailable"));
        return null;
      })
      : Promise.resolve(null);

    return Promise.all([structure, terms]).then(function (r) {
      var map = r[0], dt = r[1];
      if (map && Array.isArray(map.paragraphs)) {
        var cur = null;
        map.paragraphs.forEach(function (row) {
          // Word's own listString, where it has one. readStructuralMap marks
          // every auto-numbered item a header, so this covers "3.1(a)" items
          // as well as real section headings.
          if (row.number && row.number !== "[Unnumbered]") {
            packet.listLabels[row.anchor] = String(row.number).trim();
          }
          if (row.isHeader) {
            cur = { anchor: row.anchor, title: String(row.text || "").trim(), words: 0 };
            packet.outline.push(cur);
          } else if (cur) {
            cur.words += (String(row.text || "").match(/\S+/g) || []).length;
          }
        });
        packet.outline = packet.outline.filter(function (s) { return s.words > 0; });
      }
      if (dt && Array.isArray(dt.items)) {
        packet.definedTerms = dt.items.map(function (t) {
          return {
            term: t.term,
            at: t.anchor,
            where: t.sectionIsPointer ? "listed->body" : t.where,
            uses: t.uses,
            gist: String(t.definition || "").replace(/\s+/g, " ").slice(0, 110),
          };
        });
        // Terms the document uses without defining, and definitions with no
        // uses — both are things a revision should not make worse.
        packet.termGaps = {
          usedNeverDefined: (dt._meta.usedNeverDefined || []).map(function (x) { return x.term; }),
          definedNeverUsed: dt._meta.definedNeverUsed || [],
        };
      }
      if (!packet.outline.length) packet.degraded.push("no section outline resolved");
      if (!packet.definedTerms.length) packet.degraded.push("no defined terms resolved");
      return packet;
    });
  }

  function _packetBlock(packet) {
    if (!packet) return "";
    var lines = ["═══ CONTRACT MODEL ═══"];
    if (packet.outline.length) {
      lines.push("SECTIONS (anchor · title · words):");
      packet.outline.forEach(function (s) {
        lines.push("  " + s.anchor + " · " + s.title + " · " + s.words + "w");
      });
    }
    if (packet.definedTerms.length) {
      lines.push("", "DEFINED TERMS (term · where defined · uses · anchor):");
      packet.definedTerms.forEach(function (t) {
        lines.push("  " + t.term + " · " + t.where + " · " + t.uses + "x · " + t.at +
          (t.gist ? " — " + t.gist : ""));
      });
    }
    if (packet.termGaps && packet.termGaps.usedNeverDefined.length) {
      lines.push("", "USED BUT NOT DEFINED: " + packet.termGaps.usedNeverDefined.join(", "));
    }
    if (packet.degraded.length) {
      lines.push("", "⚠ INCOMPLETE MODEL — " + packet.degraded.join("; ") +
        ". Do not assume absence from this model means absence from the document.");
    }
    return lines.join("\n");
  }
  // ─── [/CONTEXT-PACKET] ────────────────────────────────────────────

  // ─── [CLARIFY] ────────────────────────────────────────────────────
  // Before planning anything, ask whether the request can actually be
  // carried out from what is on the page. "Make this a three-way NDA with
  // Acme Corp" can — the document supplies everything else. "Add a
  // confidentiality section" cannot: one-way or mutual, how long, what
  // survives. Guessing there produces a clause that reads fine and is
  // wrong, which is worse than asking.
  //
  // Biased hard toward asking NOTHING. The test is whether the answer
  // changes the words on the page and cannot be derived from the document
  // or a standard default — not whether a preference exists.
  //
  // TO REMOVE: delete to [/CLARIFY] + its stage in _runPlan + the
  // "clarify" case in _renderOverlayBody.
  var CLARIFY_MAX_QUESTIONS = 4;

  // The instruction as the planner should read it: the user's words plus
  // whatever they answered. Every prompt embeds THIS, not the raw
  // instruction, or the answers exist only in the clarify stage.
  function _instructionText(active) {
    var base = String((active && active.instruction) || "").trim();
    var answered = ((active && active.clarifications) || []).filter(function (c) {
      return c.answer;
    });
    if (!answered.length) return base;
    return base + "\n\nThe client answered these before work started — treat the " +
      "answers as part of the instruction:\n" +
      answered.map(function (c) {
        return "  • " + c.question + "\n    → " + c.answer;
      }).join("\n");
  }

  function _buildClarifyPrompt(active) {
    return [
      "A client has asked for a change to the contract modelled below.",
      "Before any drafting starts: can this be carried out from what is here,",
      "or would you have to guess at something that changes the words on the page?",
      "",
      "Return JSON only:",
      "{",
      '  "canProceed": true,',
      '  "questions": [',
      '    { "id": "q1", "question": "How long should confidentiality survive termination?",',
      '      "why": "the clause cannot be drafted without a term",',
      '      "suggestion": "5 years", "options": ["3 years", "5 years", "perpetual for trade secrets"] }',
      "  ]",
      "}",
      "",
      "ASK ONLY IF ALL THREE ARE TRUE:",
      "1. The answer changes the actual text that would be drafted.",
      "2. It cannot be read off the document, inferred from the request, or",
      "   covered by the ordinary default for this kind of agreement.",
      "3. Getting it wrong would produce a clause that reads fine but is wrong —",
      "   not merely one the client might have phrased differently.",
      "",
      "THE CASE WORTH ASKING ABOUT — a change to WHO the parties are does not",
      "just rename things. It creates relationships the two-party text never had",
      "to answer, and the document cannot tell you which one is meant:",
      "- Adding a party: do the obligations run between every pair of parties, or",
      "  only between one hub party and each of the others? A two-way NDA made",
      "  three-way is silent on whether B may disclose A's information to C.",
      "- Carve-outs written for one named counterparty: do they now cover the new",
      "  party too, or stay specific to the original one?",
      "- Shared mechanics — costs, notice, consent, voting — do they now run",
      "  across all parties or only the ones involved in a given matter?",
      "Ask about the one that actually bites in THIS document; do not ask all three.",
      "",
      "DO NOT ASK:",
      "- For confirmation of something the request already says. If the request",
      "  names the new party, do not ask who it is.",
      "- About style, tone, aggressiveness, or formatting.",
      "- Anything the contract model below already answers.",
      "- Anything you could reasonably draft and flag for review instead.",
      "- More than " + CLARIFY_MAX_QUESTIONS + " questions. If you have more than that, the request is",
      "  clear enough and you are asking about preferences.",
      "",
      "Most requests need NO questions. An empty list is a good outcome, not a",
      "failure — but a request that changes the PARTIES usually has exactly one",
      "question in it, and it is the one above.",
      "",
      "Each question must be answerable in a few words. `suggestion` is what you",
      "would use if the client does not answer. `options` is optional — 2-4 common",
      "answers, only where the choice is genuinely a short list.",
      "",
      "═══ REQUEST ═══",
      String((active && active.instruction) || "").trim(),
      "",
      _packetBlock(active && active.packet),
    ].filter(Boolean).join("\n");
  }

  // Resolves with the questions to ask (possibly none). Never rejects: a
  // failed clarify pass means we proceed, exactly as we did before this
  // stage existed.
  function _runClarifyPass() {
    if (!_egActive) return Promise.resolve([]);
    return _aiJsonCall(_buildClarifyPrompt(_egActive),
      { canProceed: "boolean", questions: "object" })
      .then(function (r) {
        if (!_egActive || !r) return [];
        var raw = Array.isArray(r.questions) ? r.questions : [];
        return raw.map(function (q, i) {
          return {
            id: String((q && q.id) || ("q" + (i + 1))),
            question: String((q && q.question) || "").trim(),
            why: String((q && q.why) || "").trim(),
            suggestion: String((q && q.suggestion) || "").trim(),
            options: (q && Array.isArray(q.options))
              ? q.options.map(function (o) { return String(o).trim(); })
                .filter(Boolean).slice(0, 4)
              : [],
            answer: "",
          };
        }).filter(function (q) { return q.question; })
          .slice(0, CLARIFY_MAX_QUESTIONS);
      })
      .catch(function (err) {
        // A cancel must stay a cancel — swallowing it here would let the
        // chain walk on to strategy after the user hit Cancel.
        if (err && (err.name === "AbortError" || /cancel/i.test(String(err.message)))) throw err;
        if (_egActive) _egActive.clarifyFailed = (err && err.message) || "check failed";
        return [];
      });
  }

  // Release a run parked on the questions. Safe to call when nothing is
  // parked — close and cancel both call it unconditionally.
  function _resolveClarify() {
    if (!_egActive || typeof _egActive._clarifyResolve !== "function") return;
    var fn = _egActive._clarifyResolve;
    _egActive._clarifyResolve = null;
    try { fn(); } catch (_) {}
  }

  function _bodyClarifying() {
    return _bodyHeader() +
      _stageStrip("clarifying") +
      '<div class="_eg_status_box">' +
        '<div class="_eg_status_dot"></div>' +
        '<div>Checking whether anything needs to be settled before drafting…</div>' +
      '</div>' +
      '<div class="_eg_actions_row">' +
        '<button id="_eg_cancel_plan" type="button" class="_eg_btn_secondary">Cancel</button>' +
      '</div>';
  }

  function _bodyClarify() {
    var qs = _egActive.clarifyQuestions || [];
    var rows = qs.map(function (q, i) {
      var opts = q.options.map(function (o) {
        return '<button type="button" class="_eg_clar_opt" data-eg-clar-fill="' + _esc(q.id) +
          '" data-eg-clar-val="' + _esc(o) + '">' + _esc(o) + '</button>';
      }).join("");
      // Each row states its own state, and flips the moment they type, so
      // "there is something for me to do here" survives being one card
      // among several rather than relying on the header alone.
      var answered = !!q.answer;
      return '<div class="_eg_clar_row' + (answered ? " _eg_clar_done" : "") +
          '" data-eg-clar-row="' + _esc(q.id) + '">' +
        '<div class="_eg_clar_q"><span class="_eg_clar_n">' + (i + 1) + '</span>' +
          _esc(q.question) + '</div>' +
        (q.why ? '<div class="_eg_clar_why">' + _esc(q.why) + '</div>' : '') +
        (opts ? '<div class="_eg_clar_opts">' + opts + '</div>' : '') +
        '<input type="text" class="_eg_clar_input" data-eg-clar-id="' + _esc(q.id) + '" ' +
          'value="' + _esc(q.answer || "") + '" ' +
          'placeholder="' + _esc(q.suggestion ? "Type your answer, or leave blank to use: " +
            q.suggestion : "Type your answer, or leave blank and I'll decide") + '" />' +
        '<div class="_eg_clar_state">' +
          '<span class="_eg_clar_todo">Needs your answer</span>' +
          '<span class="_eg_clar_ok">✓ Answered</span>' +
        '</div>' +
      '</div>';
    }).join("");
    // This is the one screen that needs something FROM the reader, sitting
    // in a chat full of things ELI is telling them. It gets a header that
    // reads as a question being asked, not a section label.
    return _bodyHeader() +
      _stageStrip("clarifying") +
      '<div class="_eg_ask_head">' +
        '<span class="_eg_ask_mark">?</span>' +
        '<div>' +
          '<div class="_eg_ask_title">' +
            (qs.length === 1 ? 'One question before I start'
              : qs.length + ' questions before I start') +
            '<span class="_eg_ask_pill">Waiting for you</span>' + '</div>' +
          '<div class="_eg_ask_sub">These change what actually gets drafted and the ' +
            'document doesn’t answer them. Leave any blank and I’ll decide ' +
            'it myself, then flag it on the edit.</div>' +
        '</div>' +
      '</div>' +
      '<div class="_eg_ask_list">' + rows + '</div>' +
      '<div class="_eg_actions_row _eg_actions_sticky">' +
        '<button id="_eg_clar_skip" type="button" class="_eg_btn_secondary">Skip — use your judgment</button>' +
        '<button id="_eg_clar_go" type="button" class="_eg_btn_primary _eg_btn_apply">Continue →</button>' +
      '</div>';
  }

  // Both buttons do the same thing — record whatever is typed and release
  // the chain. Skip is just Continue with nothing filled in, so there is
  // no second path to keep correct.
  function _wireClarifyControls(body) {
    function collect() {
      var qs = _egActive.clarifyQuestions || [];
      body.querySelectorAll("[data-eg-clar-id]").forEach(function (inp) {
        var id = inp.getAttribute("data-eg-clar-id");
        var q = qs.find(function (x) { return x.id === id; });
        if (q) q.answer = String(inp.value || "").trim();
      });
      _egActive.clarifications = qs.map(function (q) {
        return { id: q.id, question: q.question, answer: q.answer,
          assumed: !q.answer, suggestion: q.suggestion };
      });
      eli.log.event("tool", "eli_agent_clarified", {
        asked: qs.length,
        answered: qs.filter(function (q) { return q.answer; }).length,
      });
      _resolveClarify();
    }
    body.querySelectorAll("[data-eg-clar-fill]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-eg-clar-fill");
        var inp = body.querySelector('[data-eg-clar-id="' + id + '"]');
        if (inp) {
          inp.value = btn.getAttribute("data-eg-clar-val");
          _markRow(inp);
          inp.focus();
        }
      };
    });
    // Flip the row's state as they type — the "needs your answer" marker
    // has to stop saying that the moment it stops being true, or it reads
    // as noise and they stop believing the next one.
    function _markRow(inp) {
      var row = inp.closest && inp.closest("[data-eg-clar-row]");
      if (!row) return;
      if (String(inp.value || "").trim()) row.classList.add("_eg_clar_done");
      else row.classList.remove("_eg_clar_done");
    }
    body.querySelectorAll("._eg_clar_input").forEach(function (inp) {
      inp.oninput = function () { _markRow(inp); };
      inp.onkeydown = function (ev) { if (ev.key === "Enter") collect(); };
    });
    var go = body.querySelector("#_eg_clar_go");
    if (go) go.onclick = collect;
    var skip = body.querySelector("#_eg_clar_skip");
    if (skip) skip.onclick = collect;
    var first = body.querySelector("._eg_clar_input");
    if (first) try { first.focus(); } catch (_) {}
  }

  // What the user was asked and what they said — carried into the review
  // so an assumption is visible next to the edits it shaped.
  function _renderClarifySection(list) {
    if (!list || !list.length) return "";
    var rows = list.map(function (c) {
      var ans = c.answer
        ? '<span class="_eg_clar_ans">' + _esc(c.answer) + '</span>'
        : '<span class="_eg_clar_assumed">assumed' +
          (c.suggestion ? ": " + _esc(c.suggestion) : "") + '</span>';
      return '<div class="_eg_clar_recap_row">' + _esc(c.question) + ' ' + ans + '</div>';
    }).join("");
    return '<div class="_eg_clar_recap">' +
      '<div class="_eg_clar_recap_head">What I asked before drafting</div>' + rows +
    '</div>';
  }
  // ─── [/CLARIFY] ───────────────────────────────────────────────────

  function _buildStrategyPrompt(active) {
    var tone = (active.settings && active.settings.tone) || "balanced";
    return [
      "You are a senior associate planning a contract revision pass.",
      "Read the document below + the client's instruction. Identify the AREAS where edits are warranted.",
      "Return JSON only. Do NOT propose specific edits — just identify the buckets to focus on.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"agreementType\": \"Mutual NDA\",",
      "  \"summary\": \"Tilted payment, indemnity, MFN, and termination in Colgate's favor.\",",
      "  \"buckets\": [",
      "    {\"name\": \"Payment Terms\",  \"focus\": \"extend payment timing, reduce late-fee interest, add grace period\", \"scope\": \"Article IV\"},",
      "    {\"name\": \"Indemnity\",       \"focus\": \"cap exposure, narrow trigger, add carve-outs\", \"scope\": \"§7-8\"},",
      "    {\"name\": \"MFN Protection\",  \"focus\": \"add missing MFN clause\", \"scope\": \"§11\"},",
      "    {\"name\": \"Termination\",     \"focus\": \"extend notice, add wind-down\", \"scope\": \"§10\"}",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. Identify 3-8 buckets — enough to be thorough, not so many they overlap.",
      "2. Each bucket has a unique short `name` (used downstream as a key).",
      "3. `focus` is 1-2 sentences on what kinds of edits to look for in this bucket.",
      "4. `scope` references doc sections by number/title where present.",
      "5. `summary` is 1-2 sentences describing the overall revision strategy.",
      "6. Before proposing a bucket, CHECK THE CONTRACT MODEL. If the " +
        "instruction asks for something the agreement already has, say so in " +
        "`summary` and return NO bucket for it. Proposing an edit for " +
        "something already present produces a duplicate clause that " +
        "contradicts the original — worse than doing nothing.",
      "7. `scope` MUST cite section anchors from the model (ELI_IDX_<n>) " +
        "where one applies, so the next pass reads only those sections.",
      "",
      "TONE: " + _toneGuide(tone),
      "",
      _packetBlock(active.packet),
      "",
      "═══ INSTRUCTION ═══",
      _instructionText(active),
      "",
      "═══ DOCUMENT (paragraph-indexed JSON — id, text, section) ═══",
      _docPayload(active),
    ].join("\n");
  }

  function _buildBucketPrompt(active, bucket) {
    var tone = (active.settings && active.settings.tone) || "balanced";
    var pbSnippets = (active.playbooks || []).slice(0, 8).map(function (p) {
      return "  • " + p.clauseName + " (from " + p.source + "):\n      " +
        p.preferredLanguage.replace(/\n/g, " ").slice(0, 400);
    }).join("\n");
    var pbBlock = _guidanceBlock(active) + (pbSnippets
      ? "\n═══ ELI'S PLAYBOOK — PREFERRED LANGUAGE ═══\n" + pbSnippets +
        "\nWhen proposing edits in matching categories, USE this language verbatim where it fits.\n"
      : "");
    // When the bucket is from the email agent, it carries a commentRef.
    // Inject the original commenter's verbatim language so the AI can
    // cite it in rationales + addressesComment field on each edit.
    var commentBlock = "";
    if (bucket.commentRef) {
      var c = bucket.commentRef;
      commentBlock =
        "\n═══ ORIGINAL COMMENT (from " + (c.author || "the reviewer") + ") ═══\n" +
        "Quote: \"" + (c.originalText || c.ask) + "\"\n" +
        "Severity: " + (c.severity || "med") + "\n" +
        "Comment ID: " + c.id + "\n" +
        "RULES FOR THIS BUCKET:\n" +
        " • Each edit MUST include `addressesComment: \"" + c.id + "\"` in its JSON.\n" +
        " • Reference the commenter's language in the rationale (e.g., \"Direct response to " + (c.author || "the reviewer") + "'s ask...\").\n" +
        " • If the comment is NOT actionable (vague, judgment-call, or refers to something not in the doc), return an empty edits array — the orchestrator will mark this comment as 'punted' or 'blocked'.\n";
    }
    return [
      "You are a senior associate generating specific contract edits for a SINGLE focus area.",
      "Generate every relevant edit for this bucket. Be thorough — 2-6 edits per bucket is typical.",
      "Return JSON only.",
      "",
      "OUTPUT SHAPE (example):",
      "{",
      "  \"edits\": [",
      "    {",
      "      \"type\": \"replace\",",
      "      \"paragraphId\": \"ELI_QA_14\",",
      "      \"section\": \"§4.2 Payment Terms\",",
      "      \"anchorText\": \"thirty (30) days\",",
      "      \"replacementText\": \"sixty (60) days\",",
      "      \"rationale\": \"Extends working-capital cycle.\",",
      "      \"category\": \"payment-terms\",",
      "      \"confidence\": 5,",
      "      \"requiresHumanReview\": false",
      "    }",
      "  ]",
      "}",
      "",
      "RULES:",
      "1. `anchorText` MUST be a verbatim text snippet from the document (5-20 words, unique within the paragraph).",
      "2. `paragraphId` MUST exactly match the `id` of one of the paragraphs below.",
      "3. `section`: COPY VERBATIM from the paragraph's `section` field below. If the paragraph has no section field, omit it. DO NOT invent or guess section numbers — do not infer from text content that mentions \"Section X\" inline. The orchestrator will fill in the correct section from the document's structural map; your `section` field will be overridden if it differs.",
      "4. `type`: 'replace', 'insert' (with insertPosition: 'before'|'after'), or 'delete'.",
      "5. Confidence (1-5): 5 = standard market move, 4 = reasonable, 3 = aggressive, 2-1 = unusual/risky.",
      "6. Set `requiresHumanReview: true` for judgment-heavy edits (asymmetric obligations, removing whole clauses, scope shifts).",
      "7. Categories: payment-terms, indemnity, ip, termination, mfn, audit, warranty, confidentiality, dispute-resolution, boilerplate, other.",
      "8. Don't number `id` — orchestrator will assign globally-unique ids.",
      "9. NUMBERED LISTS: Word generates the numbering. A paragraph shown here as",
      "   \"Each Party shall…\" may render as \"3.1(a) Each Party shall…\" — the \"(a)\"",
      "   is NOT in the text. Never put a list number or letter at the start of",
      "   `anchorText` (it will not be found) or `replacementText` (Word adds its own,",
      "   and the item renders as \"3.1(a) (a) Each Party…\").",
      "9b. DO NOT edit notice blocks (address / Attn / \"If to …\") or signature",
      "   blocks (\"IN WITNESS WHEREOF\", By / Name / Title). They are soft-broken",
      "   address lines and tables; a partial rewrite damages the block and",
      "   everything after it. The user is told to update those by hand. Any",
      "   edit you propose to one is discarded, so proposing it only costs you",
      "   an edit.",
      "9c. That applies to what you WRITE, not only what you aim at. Do not",
      "   add a notice-block entry (\"If to X:\" / \"Attn:\" / \"Email address:\")",
      "   or a signature block (By / Name / Title lines) as a NEW SECTION. An",
      "   insert whose text is one of those blocks is discarded wherever it is",
      "   anchored — it lands as a numbered clause and breaks the document.",
      "10. One edit per paragraph. A change affecting 3.1(a) and 3.1(b) is TWO edits,",
      "   each with its own paragraphId. Do not rewrite a whole list to renumber",
      "   it — Word renumbers by itself.",
      "11. An 'insert' adds a WHOLE NEW SECTION and nothing else. Never insert a",
      "   sub-item into an existing list — no \"(a)\", no \"5.4(b)\", no extra item",
      "   under a clause. If the new obligation belongs INSIDE an existing clause,",
      "   'replace' that clause with the fuller text instead.",
      "11a. Write the new section as its heading line, then its body, one \"\\n\" per",
      "   paragraph. Do NOT write a number or a letter anywhere in it — Word",
      "   generates the numbering, and one you type is stripped.",
      "11b. Anchor it with insertPosition 'after' on the LAST paragraph of the",
      "   section it should follow, never on a sub-item. An insert anchored to a",
      "   sub-item is moved to the section boundary before it is applied.",
      "11c. NEVER add a section with type 'replace'. Re-typing a paragraph and",
      "   appending the new section to it is the most common way this goes",
      "   wrong: it renders as a rewrite of the paragraph above, not as a new",
      "   section, and it gets no number. `anchorText` for an insert is the",
      "   paragraph you position against — it is NOT re-emitted in",
      "   `replacementText`. `replacementText` is ONLY the new section.",
      "11d. Never propose an edit to text ANOTHER edit adds. If a new section",
      "   needs a cross-reference, a carve-out or a tightened sentence, write it",
      "   into that section. A separate edit quoting text that is not yet in the",
      "   document cannot anchor, and reads as a duplicate proposal for the same",
